import csv
import io


def _fallback_parse(raw_csv):
    rows = []
    row = []
    field = []
    in_quotes = False
    at_field_start = True
    i = 0
    n = len(raw_csv)

    while i < n:
        ch = raw_csv[i]

        if in_quotes:
            if ch == '"':
                if i + 1 < n and raw_csv[i + 1] == '"':
                    field.append('"')
                    i += 2
                    continue
                in_quotes = False
            else:
                field.append(ch)
            i += 1
            continue

        if ch == '"' and at_field_start:
            in_quotes = True
            at_field_start = False
        elif ch == ',':
            row.append("".join(field))
            field = []
            at_field_start = True
        elif ch == "\r" or ch == "\n":
            row.append("".join(field))
            rows.append(row)
            row = []
            field = []
            at_field_start = True
            if ch == "\r" and i + 1 < n and raw_csv[i + 1] == "\n":
                i += 1
        else:
            field.append(ch)
            at_field_start = False
        i += 1

    if row or field or not at_field_start:
        row.append("".join(field))
        rows.append(row)

    return rows


def parse_csv(raw_csv: str):
    if not isinstance(raw_csv, str):
        raw_csv = str(raw_csv)

    if raw_csv.startswith("\ufeff"):
        raw_csv = raw_csv[1:]

    old_limit = csv.field_size_limit()
    try:
        try:
            csv.field_size_limit(max(old_limit, len(raw_csv) + 1))
        except (OverflowError, ValueError):
            pass
        try:
            reader = csv.reader(
                io.StringIO(raw_csv, newline=""),
                delimiter=",",
                quotechar='"',
                doublequote=True,
                strict=False,
            )
            parsed = [list(row) for row in reader]
        except csv.Error:
            parsed = _fallback_parse(raw_csv)
    finally:
        try:
            csv.field_size_limit(old_limit)
        except (OverflowError, ValueError):
            pass

    if not parsed:
        return {"columns": [], "rows": []}

    expected_width = 9
    nonempty_indices = [
        i for i, row in enumerate(parsed)
        if row and any(value != "" for value in row)
    ]

    if not nonempty_indices:
        return {"columns": [], "rows": []}

    exact_indices = [
        i for i in nonempty_indices if len(parsed[i]) == expected_width
    ]

    if exact_indices:
        header_index = exact_indices[0]
    else:
        header_index = min(
            nonempty_indices,
            key=lambda i: (abs(len(parsed[i]) - expected_width), i),
        )

    columns = list(parsed[header_index])
    data_rows = [list(row) for row in parsed[header_index + 1:]]

    width = max(
        [expected_width, len(columns)] + [len(row) for row in data_rows]
    )

    existing = set(columns)
    next_number = 1
    while len(columns) < width:
        name = "column_" + str(next_number)
        next_number += 1
        while name in existing:
            name = "column_" + str(next_number)
            next_number += 1
        columns.append(name)
        existing.add(name)

    normalized_rows = []
    for row in data_rows:
        if len(row) < width:
            row.extend([""] * (width - len(row)))
        normalized_rows.append(row)

    return {"columns": columns, "rows": normalized_rows}
